//! The boot migration gate (`Database::CheckRequiredMigrations`,
//! `Database.cpp:570-625`): every migration file known to the
//! build must be recorded in the database's `migrations` table;
//! extras only warn. Expected lists are generated by `build.rs`
//! from the same glob the C++ build uses.

use std::collections::BTreeSet;

use mysql::prelude::Queryable;

use crate::DbError;

include!(concat!(env!("OUT_DIR"), "/migrations_list.rs"));

/// The four gated databases (`Master::_StartDB` order:
/// World, Character, Login, Logs).
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum MigrationDb {
    World,
    Characters,
    Logon,
    Logs,
}

impl MigrationDb {
    /// Expected migration names for this database, sorted.
    #[must_use]
    pub fn expected(self) -> &'static [&'static str] {
        match self {
            MigrationDb::World => MIGRATIONS_WORLD,
            MigrationDb::Characters => MIGRATIONS_CHARACTERS,
            MigrationDb::Logon => MIGRATIONS_LOGON,
            MigrationDb::Logs => MIGRATIONS_LOGS,
        }
    }
}

/// Gate verdict. `missing` non-empty refuses boot; `extra` only
/// warns (`Database.cpp:606-623`).
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct GateOutcome {
    pub missing: Vec<String>,
    pub extra: Vec<String>,
}

impl GateOutcome {
    #[must_use]
    pub fn passes(&self) -> bool {
        self.missing.is_empty()
    }
}

/// Pure set comparison behind the gate. Applied names collapse
/// duplicates (C++ uses `std::set`); output order is sorted,
/// matching the C++ set iteration in its log lines.
#[must_use]
pub fn check_gate(expected: &[&str], applied: &[String]) -> GateOutcome {
    let applied_set: BTreeSet<&str> = applied.iter().map(String::as_str).collect();
    let expected_set: BTreeSet<&str> = expected.iter().copied().collect();
    GateOutcome {
        missing: expected_set
            .difference(&applied_set)
            .map(|s| (*s).to_string())
            .collect(),
        extra: applied_set
            .difference(&expected_set)
            .map(|s| (*s).to_string())
            .collect(),
    }
}

/// Run the gate over a live connection: `SELECT * FROM
/// migrations` (first column), then `SELECT DATABASE()` for the
/// name the C++ puts in its log lines.
///
/// # Errors
///
/// Returns [`DbError`] on driver failure, including a missing
/// `migrations` table (the C++ `Query` returns null there and
/// every expected migration reads as missing; the Rust driver
/// surfaces it as an error so boot fails either way).
pub fn check_required_migrations(
    conn: &mut mysql::Conn,
    db: MigrationDb,
) -> Result<(String, GateOutcome), DbError> {
    let applied: Vec<String> = conn.query("SELECT * FROM `migrations`")?;
    let db_name: Option<String> = conn.query_first("SELECT DATABASE()")?;
    let db_name = db_name.ok_or(DbError::NoRow)?;
    Ok((db_name, check_gate(db.expected(), &applied)))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn gate_set_semantics() {
        let expected = ["20210101_a", "20210102_b", "20210103_c"];
        let applied = vec![
            "20210101_a".to_string(),
            "20210103_c".to_string(),
            "20210103_c".to_string(), // duplicate collapses
            "19990101_extra".to_string(),
        ];
        let outcome = check_gate(&expected, &applied);
        assert_eq!(outcome.missing, vec!["20210102_b"]);
        assert_eq!(outcome.extra, vec!["19990101_extra"]);
        assert!(!outcome.passes());

        let complete: Vec<String> = expected.iter().map(|s| (*s).to_string()).collect();
        let outcome = check_gate(&expected, &complete);
        assert!(outcome.missing.is_empty() && outcome.passes());
        assert!(outcome.extra.is_empty());
    }

    #[test]
    fn generated_lists_match_repo_census() {
        // Census from the architecture document section 5 and the
        // Phase 3 inventory: 1005 world / 18 characters / 6 logon /
        // 6 logs. A drift here means migration files were added or
        // removed; update the census deliberately.
        assert_eq!(MIGRATIONS_WORLD.len(), 1005);
        assert_eq!(MIGRATIONS_CHARACTERS.len(), 18);
        assert_eq!(MIGRATIONS_LOGON.len(), 6);
        assert_eq!(MIGRATIONS_LOGS.len(), 6);
        // Names are timestamps without the _db.sql suffix.
        assert!(
            MIGRATIONS_WORLD
                .iter()
                .all(|n| n.chars().all(|c| c.is_ascii_digit() || c == '_'))
        );
        assert_eq!(MIGRATIONS_WORLD[0], "20210515110157");
    }
}
